import {build} from "esbuild";
import {mkdir, writeFile} from "node:fs/promises";

const result = await build({
  entryPoints: [new URL("../viewer/app.ts", import.meta.url).pathname],
  bundle: true, write: false, format: "iife", platform: "browser", target: "es2022",
  minify: true, legalComments: "inline",
});
const directory = new URL("../src/generated/", import.meta.url);
await mkdir(directory, {recursive: true});
await writeFile(new URL("three-viewer.ts", directory),
  "// Generated by npm run build:viewer.\nexport const threeViewerScript: string = " +
  JSON.stringify(result.outputFiles[0].text) + ";\n");
console.log(`3D viewer: ${(result.outputFiles[0].contents.length / 1024).toFixed(0)} KiB bundled`);
